package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
	"github.com/stretchr/testify/assert"
)

func TestTmpVerifyProxyBalancerWithNoTargets(t *testing.T) {
	e := echo.New()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	rec := httptest.NewRecorder()
	c := e.NewContext(req, rec)

	h := Proxy(NewRoundRobinBalancer([]*ProxyTarget{}))(func(c echo.Context) error {
		return c.String(http.StatusOK, "test")
	})

	err := h(c)
	if assert.Error(t, err) {
		he, ok := err.(*echo.HTTPError)
		if assert.True(t, ok) {
			assert.Equal(t, http.StatusBadGateway, he.Code)
		}
	}

	// also exercise the random balancer and the full HTTP path (must not panic)
	e2 := echo.New()
	e2.Use(Proxy(NewRandomBalancer([]*ProxyTarget{})))
	rec2 := httptest.NewRecorder()
	e2.ServeHTTP(rec2, httptest.NewRequest(http.MethodGet, "/", nil))
	assert.Equal(t, http.StatusBadGateway, rec2.Code)
}

Run: cd /echo && go test ./middleware/ -run 'TestTmpVerifyProxyBalancerWithNoTargets' -v

